package com.personal.assistant.module.inbox.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.personal.assistant.common.exception.*;import com.personal.assistant.module.inbox.dto.*;import com.personal.assistant.module.inbox.entity.InboxItem;import com.personal.assistant.module.inbox.mapper.InboxItemMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service public class InboxService{private static final Set<String>TYPES=Set.of("TASK","REMINDER","EXPENSE","LEARNING","NOTE");private final InboxItemMapper mapper;public InboxService(InboxItemMapper mapper){this.mapper=mapper;}public List<InboxItem> list(Long uid,String status){return mapper.selectList(new LambdaQueryWrapper<InboxItem>().eq(InboxItem::getUserId,uid).eq(status!=null,InboxItem::getStatus,status).orderByDesc(InboxItem::getCreatedAt).last("limit 200"));}@Transactional public InboxItem create(Long uid,InboxCreateRequest request){Suggestion suggestion=suggest(request.content());InboxItem item=new InboxItem();item.setUserId(uid);item.setContent(request.content().trim());item.setSuggestedType(suggestion.type());item.setConfidence(suggestion.confidence());item.setReason(suggestion.reason());item.setStatus("PENDING");item.setCreatedAt(LocalDateTime.now());mapper.insert(item);return item;}@Transactional public void confirm(Long uid,Long id,InboxConfirmRequest request){if(!TYPES.contains(request.confirmedType()))throw new BusinessException(ErrorCode.VALIDATION_ERROR,"收件箱类型不合法");InboxItem item=require(uid,id);item.setConfirmedType(request.confirmedType());item.setStatus("CONFIRMED");item.setConfirmedAt(LocalDateTime.now());mapper.updateById(item);}@Transactional public void archive(Long uid,Long id){InboxItem item=require(uid,id);item.setStatus("ARCHIVED");item.setConfirmedAt(LocalDateTime.now());mapper.updateById(item);}private InboxItem require(Long uid,Long id){InboxItem item=mapper.selectById(id);if(item==null||!uid.equals(item.getUserId()))throw new BusinessException(ErrorCode.NOT_FOUND,"收件箱记录不存在");return item;}private Suggestion suggest(String content){String text=content.toLowerCase();if(text.matches(".*(¥|￥|元|消费|付款|买了|支出|报销).*"))return new Suggestion("EXPENSE",BigDecimal.valueOf(0.85),"识别到金额或消费关键词");if(text.matches(".*(提醒|闹钟|别忘|明天|后天|点钟|到期).*"))return new Suggestion("REMINDER",BigDecimal.valueOf(0.82),"识别到时间或提醒关键词");if(text.matches(".*(学习|阅读|课程|复习|笔记|知识).*"))return new Suggestion("LEARNING",BigDecimal.valueOf(0.78),"识别到学习关键词");if(text.matches(".*(完成|处理|待办|任务|需要|todo).*"))return new Suggestion("TASK",BigDecimal.valueOf(0.72),"识别到行动关键词");return new Suggestion("NOTE",BigDecimal.valueOf(0.55),"未识别到明确业务场景，建议作为普通记录");}private record Suggestion(String type,BigDecimal confidence,String reason){}}
